# ml/persistence/models.py
"""SQLAlchemy model definitions for Phase 7 persistence.

Only the minimal tables required for storing monitoring data are defined:

* ``Session`` – a monitoring run.
* ``PostureMetric`` – a single posture/risk snapshot belonging to a session.
* ``Alert`` – an alert event generated by the TemporalRiskEngine.
* ``UserSetting`` – simple key/value storage for the front‑end settings.

All tables use ``INTEGER PRIMARY KEY AUTOINCREMENT`` for the id field.
"""

from datetime import datetime
from sqlalchemy import Column, Integer, Float, String, DateTime, Boolean, ForeignKey, Text
from sqlalchemy.orm import relationship
from .db import Base
from sqlalchemy import UniqueConstraint

class Session(Base):
    __tablename__ = "sessions"
    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=True, index=True)
    start_timestamp = Column(Float, nullable=False)
    end_timestamp = Column(Float, nullable=True)
    status = Column(String(20), nullable=False, default="ACTIVE")  # ACTIVE, COMPLETED, FAILED
    created_at = Column(DateTime, default=datetime.utcnow)

    # relationships
    user = relationship("User", back_populates="sessions")
    metrics = relationship("PostureMetric", back_populates="session", cascade="all, delete-orphan")
    alerts = relationship("Alert", back_populates="session", cascade="all, delete-orphan")

class PostureMetric(Base):
    __tablename__ = "posture_metrics"
    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=True, index=True)
    session_id = Column(Integer, ForeignKey("sessions.id"), nullable=False, index=True)
    timestamp = Column(Float, nullable=False)
    posture = Column(String(10), nullable=False)
    confidence = Column(Float, nullable=False)
    risk_score = Column(Float, nullable=False)
    risk_level = Column(String(10), nullable=False)
    temporal_state = Column(String(20), nullable=False)
    viewpoint = Column(String(20), nullable=True)
    tracking_state = Column(String(20), nullable=True)
    pose_valid = Column(Boolean, nullable=True)

    user = relationship("User", back_populates="posture_metrics")
    session = relationship("Session", back_populates="metrics")

class Alert(Base):
    __tablename__ = "alerts"
    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=True, index=True)
    session_id = Column(Integer, ForeignKey("sessions.id"), nullable=False, index=True)
    timestamp = Column(Float, nullable=False)
    posture = Column(String(10), nullable=False)
    risk_score = Column(Float, nullable=False)
    risk_level = Column(String(10), nullable=False)
    alert_type = Column(String(20), nullable=False, default="RISK_ALERT")
    message = Column(Text, nullable=True)
    voice_message = Column(Text, nullable=True)
    viewpoint = Column(String(20), nullable=True)
    risk_state = Column(String(20), nullable=True)

    user = relationship("User", back_populates="alerts")
    session = relationship("Session", back_populates="alerts")

class UserSetting(Base):
    __tablename__ = "user_settings"
    id = Column(Integer, primary_key=True, index=True)
    user_id = Column(Integer, ForeignKey("users.id"), nullable=True, index=True)
    key = Column(String(50), nullable=False)
    value = Column(String(200), nullable=True)
    # Unique constraint per user
    __table_args__ = (UniqueConstraint('user_id', 'key', name='_user_key_uc'),)

    user = relationship("User", back_populates="settings")

class User(Base):
    __tablename__ = "users"
    id = Column(Integer, primary_key=True, index=True)
    name = Column(String(100), nullable=False)
    email = Column(String(150), unique=True, nullable=False, index=True)
    password_hash = Column(String(200), nullable=False)
    created_at = Column(DateTime, default=datetime.utcnow)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    is_active = Column(Boolean, default=True)

    # relationships
    sessions = relationship("Session", back_populates="user")
    posture_metrics = relationship("PostureMetric", back_populates="user")
    alerts = relationship("Alert", back_populates="user")
    settings = relationship("UserSetting", back_populates="user")
